using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Mbb.Archive.Modules.Archive.Domain.Records;
namespace Mbb.Archive.Modules.Archive.Infrastructure.Persistence.Configurations;
internal sealed class ArchiveRecordConfiguration:IEntityTypeConfiguration<ArchiveRecord>{public void Configure(EntityTypeBuilder<ArchiveRecord>b){b.ToTable("records","archive");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasConversion(x=>x.Value,x=>new ArchiveRecordId(x)).ValueGeneratedNever();b.Property(x=>x.DocumentId).HasColumnName("document_id");b.Property(x=>x.DocumentVersionId).HasColumnName("document_version_id");b.Property(x=>x.OriginalStorageKey).HasColumnName("original_storage_key").HasMaxLength(1000);b.Property(x=>x.Sha256Hash).HasColumnName("sha256_hash").HasMaxLength(64);b.Property(x=>x.MimeType).HasColumnName("mime_type").HasMaxLength(255);b.Property(x=>x.SizeBytes).HasColumnName("size_bytes");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ClassificationCode).HasColumnName("classification_code").HasMaxLength(100);b.Property(x=>x.RetentionRuleCode).HasColumnName("retention_rule_code").HasMaxLength(100);b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.DeclaredAt).HasColumnName("declared_at");b.Property(x=>x.ConcurrencyVersion).HasColumnName("concurrency_version").IsConcurrencyToken();b.Ignore(x=>x.DomainEvents);b.HasIndex(x=>x.DocumentVersionId).IsUnique();}}
internal sealed class InboxConfiguration:IEntityTypeConfiguration<InboxMessage>{public void Configure(EntityTypeBuilder<InboxMessage>b){b.ToTable("inbox_messages","archive");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EventName).HasColumnName("event_name").HasMaxLength(200);b.Property(x=>x.ProcessedAt).HasColumnName("processed_at");}}
internal sealed class OutboxConfiguration:IEntityTypeConfiguration<OutboxMessage>{public void Configure(EntityTypeBuilder<OutboxMessage>b){b.ToTable("outbox_messages","archive");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EventName).HasColumnName("event_name").HasMaxLength(200);b.Property(x=>x.Payload).HasColumnName("payload").HasColumnType("jsonb");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.Property(x=>x.NextAttemptAt).HasColumnName("next_attempt_at");b.Property(x=>x.ProcessedAt).HasColumnName("processed_at");b.Property(x=>x.AttemptCount).HasColumnName("attempt_count");b.Property(x=>x.LockedBy).HasColumnName("locked_by").HasMaxLength(200);b.Property(x=>x.LockedUntil).HasColumnName("locked_until");b.Property(x=>x.DeadLetteredAt).HasColumnName("dead_lettered_at");b.Property(x=>x.LastError).HasColumnName("last_error").HasMaxLength(4000);}}
